CREATE TABLE previews (id TEXT PRIMARY KEY, targetId TEXT NOT NULL, revision TEXT NOT NULL, target TEXT NOT NULL, route TEXT NOT NULL, attempted INTEGER NOT NULL DEFAULT 0, removed INTEGER NOT NULL DEFAULT 0, desired TEXT NOT NULL CHECK(desired IN ('published','removed')));
CREATE UNIQUE INDEX one_preview_target ON previews(targetId) WHERE removed=0;
CREATE TABLE preview_operations (id TEXT PRIMARY KEY, previewId TEXT NOT NULL REFERENCES previews(id), action TEXT NOT NULL CHECK(action IN ('publish','unpublish')), status TEXT NOT NULL CHECK(status IN ('accepted','running','succeeded','partial','failed')), error TEXT, createdAt TEXT NOT NULL, finishedAt TEXT);
CREATE UNIQUE INDEX one_active_preview_operation ON preview_operations(previewId) WHERE status IN ('accepted','running');
ALTER TABLE requests RENAME TO lifecycle_requests;
CREATE TABLE requests (id TEXT PRIMARY KEY, payload TEXT NOT NULL, operation TEXT REFERENCES operations(id), previewOperation TEXT REFERENCES preview_operations(id), CHECK((operation IS NULL) != (previewOperation IS NULL)));
INSERT INTO requests(id,payload,operation) SELECT id,payload,operation FROM lifecycle_requests;
DROP TABLE lifecycle_requests;
ALTER TABLE reservations RENAME TO lifecycle_reservations;
CREATE TABLE reservations (key TEXT PRIMARY KEY, resource TEXT REFERENCES resources(id), preview TEXT REFERENCES previews(id), CHECK((resource IS NULL) != (preview IS NULL)));
INSERT INTO reservations(key,resource) SELECT key,resource FROM lifecycle_reservations;
DROP TABLE lifecycle_reservations;
